#!/usr/bin/env python3
"""Exercise checkout Settings through a real Quickshell owner in isolated XDG roots."""
import json
import re
import os
from pathlib import Path
import subprocess
import tempfile
import time
import hashlib
import sys

REPOSITORY = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(REPOSITORY))


def main():
    record = {}
    with tempfile.TemporaryDirectory(prefix='blox-settings-proof-') as temporary:
        root = Path(temporary)
        for name in ('config', 'state', 'data', 'cache', 'host'):
            (root / name).mkdir(mode=0o700)
        from shell.scripts.hyprland_settings import ENTRYPOINT_LINE, MODULE, MARKER, load_assertion
        entrypoint = root / 'config/hypr/hyprland.lua'
        entrypoint.parent.mkdir(mode=0o700)
        entrypoint.write_text(ENTRYPOINT_LINE + '\n')
        module = root / 'config/blox' / MODULE
        module.parent.mkdir(mode=0o700)
        module.write_text(MARKER + '-- Generated by Blox. Edit Settings, not this file.\n')
        module.chmod(0o600)
        host = root / 'host'
        for name in ('modules', 'services', 'shared', 'scripts', 'assets', 'popouts'):
            (host / name).symlink_to(REPOSITORY / 'shell' / name)
        (host / 'shell.qml').write_text('''import QtQuick
import Quickshell
import Quickshell.Io
import qs.services
Scope {
    SettingsController { id: owner }
    IpcHandler {
        target: "settings-proof"
        function snapshot(): string { return JSON.stringify(owner.typedResult); }
    }
}
''')
        env = {**os.environ, 'XDG_CONFIG_HOME': str(root / 'config'), 'XDG_STATE_HOME': str(root / 'state'),
               'XDG_DATA_HOME': str(root / 'data'), 'XDG_CACHE_HOME': str(root / 'cache'),
               'BLOX_USER_DATA_DIR': str(root / 'data/blox-user'), 'BLOX_DATA_DIR': str(REPOSITORY / 'themes'),
               'QT_QPA_PLATFORM': 'offscreen', 'QML2_IMPORT_PATH': str(host)}
        processes = []
        def start():
            log = (root / ('shell-' + str(len(processes)) + '.log')).open('w')
            process = subprocess.Popen(['quickshell', '-p', str(host / 'shell.qml')], env=env, stdout=log, stderr=subprocess.STDOUT)
            processes.append((process, log))
            env['QUICKSHELL_IPC_PID'] = str(process.pid)
            for _ in range(100):
                probe = subprocess.run(['quickshell', 'ipc', '--pid', str(process.pid), 'call', 'settings-proof', 'snapshot'], capture_output=True, text=True)
                if probe.returncode == 0:
                    time.sleep(0.15)
                    return process
                if process.poll() is not None:
                    raise RuntimeError('Proof shell failed to start')
                time.sleep(0.05)
            raise RuntimeError('Proof owner unavailable')
        def cli(*arguments):
            completed = subprocess.run([sys.executable, str(REPOSITORY / 'shell/scripts/bloxctl.py'), 'settings', *arguments, '--json'], env=env, capture_output=True, text=True, timeout=10)
            return completed.returncode, json.loads(completed.stdout)
        try:
            process = start()
            code, initial = cli('get')
            assert code == 0 and initial['data']['revision'] == 0, initial
            assert not (root / 'config/blox/settings.json').exists()
            code, changed = cli('set', 'bar.style.edgeInset', '7', '--revision', '0')
            assert code == 0 and changed['data']['revision'] == 1, changed
            snapshot = json.loads(subprocess.check_output(['quickshell', 'ipc', '--pid', str(process.pid), 'call', 'settings-proof', 'snapshot'], text=True))
            assert snapshot['code'] == changed['code'] and snapshot['data']['settings'] == changed['data']['settings']
            code, stale = cli('set', 'bar.style.edgeInset', '9', '--revision', '0')
            assert code != 0 and stale['code'] == 'conflict'
            saved = (root / 'config/blox/settings.json').read_bytes()
            process.terminate(); process.wait(timeout=5)
            start()
            code, cold = cli('get')
            assert code == 0 and cold['data']['settings']['bar']['style']['edgeInset'] == 7
            assert (root / 'config/blox/settings.json').read_bytes() == saved
            record['realQuickshellOwner'] = {'result': 'pass', 'cliQmlAgreement': True, 'staleRevision': stale['code'],
                'coldStartRevision': cold['data']['revision'], 'coldStartDigest': hashlib.sha256(saved).hexdigest(),
                'installedShell': False}
        finally:
            for process, log in processes:
                if process.poll() is None:
                    process.terminate(); process.wait(timeout=5)
                log.close()
        # All mutation and generated assets remain below the temporary roots.
        old = os.environ.copy()
        os.environ.update(env)
        try:
            from shell.scripts.settings_document import SettingsDocument
            from shell.scripts.bundle_runtime import run as bundle
            from themes.lib.blox_theme.core import load_theme
            from themes.lib.blox_theme.generators import save_theme_source
            from themes.lib.blox_theme.component_bundle import export_components
            from themes.lib.blox_theme.apply_owners import create_apply
            from themes.lib.blox_theme.apply_coordinator import ApplyError
            from themes.lib.blox_theme import runtime
            owner = SettingsDocument()
            _, theme = load_theme('catppuccin-frappe')
            theme['id'] = 'final-proof'; theme['name'] = 'Final proof'
            theme['colours']['accent'] = '#82aaff'
            source = save_theme_source(theme, root / 'data/blox-user/themes')
            archive = root / 'proof.blox-theme'
            export_components(theme, owner.get().data, archive, 'minimal', wallpaper=False)
            reviewed = bundle('inspect', {'theme': 'catppuccin-frappe', 'path': str(archive)}, owner)
            request = {'theme': 'catppuccin-frappe', 'path': str(archive), 'digest': reviewed['digest'],
                       'revision': reviewed['settingsRevision'], 'components': reviewed['components'],
                       'replace': True, 'sourceDigest': reviewed['sourceDigest']}
            imported = bundle('import', request, owner)
            assert json.loads(Path(imported['path']).read_text())['colours']['accent'] == '#82aaff'
            assert runtime.current_generation() is None
            record['themeComponent'] = {'result': 'pass', 'component': 'appearance', 'activatedByImport': False}
            for name in ('btop', 'micro'):
                outcome = owner.set('targets.' + name + '.enabled', True, owner.get().revision)
                assert outcome.ok
            loaded_receipt = b''
            def command(argv, **kwargs):
                nonlocal loaded_receipt
                if argv[1:] == ['reload']:
                    marker = re.search(rb'^_G\.__blox_hyprland_settings = "([0-9]+:[0-9a-f]{64})"$', module.read_bytes(), re.M)
                    loaded_receipt = marker.group(1) if marker else b''
                if argv[1] == 'eval':
                    matched = argv[2] == load_assertion(loaded_receipt.decode('ascii'))
                    return subprocess.CompletedProcess(argv, 0 if matched else 7,
                                                       b'ok\n' if matched else b'error: receipt mismatch', b'')
                output = b'no flags were set\n' if argv[-1] == 'configerrors' else b'ok\n'
                return subprocess.CompletedProcess(argv, 0, output, b'')
            coordinator, apply_request = create_apply(str(source), hyprland_runner=command)
            original = coordinator.owners['btop'].apply
            def fail(payload):
                original(payload)
                raise RuntimeError('Independent failure fixture')
            coordinator.owners['btop'].apply = fail
            partial = coordinator.apply(apply_request)
            assert partial['code'] == 'partial', partial
            coordinator.owners['btop'].apply = original
            retried = coordinator.retry_failed_targets()
            assert retried['code'] == 'ok'
            link, _ = runtime.phase7_loader_specs(runtime.state_dir())['btop']
            before = os.readlink(link)
            link.unlink(); link.write_bytes(b'foreign drift fixture\n')
            drift = False
            try: coordinator.roll_back()
            except ApplyError: drift = True
            assert drift and link.read_bytes() == b'foreign drift fixture\n'
            link.unlink(); link.symlink_to(before)
            rolled = coordinator.roll_back()
            assert rolled['code'] == 'rolled-back' and runtime.current_generation() is None
            record['applyFixture'] = {'result': 'pass', 'independentFailure': partial['code'], 'retry': retried['code'],
                                     'observedLoaderDriftBlocksRollback': drift, 'foreignBytesPreserved': True,
                                     'rollback': rolled['code'], 'liveHyprlandReload': False}
        finally:
            os.environ.clear(); os.environ.update(old)
    print(json.dumps(record, indent=2, sort_keys=True))


if __name__ == '__main__':
    main()
